import {h,render} from 'preact';
import {useState,useEffect,useLayoutEffect,useRef} from 'preact/hooks';
import htm from 'htm';
const html=htm.bind(h);
const ICONS=await fetch('/vendor/icons.json').then(r=>r.json());
const modes={search:{label:'搜索论文',icon:'Search'},recommend:{label:'为我推荐',icon:'Compass'},mixed:{label:'搜索＋推荐',icon:'Layers'}};
const toolNames={search_papers:'搜索论文',recommend_papers:'推荐论文',read_paper:'读取原摘要',finalize:'核验引用并提交'};
const statusNames={completed:'已完成',no_results:'没有匹配结果',partial:'部分完成',failed:'请求未完成',cancelled:'已取消',running:'执行中',stopping:'停止请求已发送'};
function Icon({name,size=18,...props}){return h('svg',{width:size,height:size,viewBox:'0 0 24 24',fill:'none',stroke:'currentColor','stroke-width':1.7,'stroke-linecap':'round','stroke-linejoin':'round','aria-hidden':'true',...props},...(ICONS[name]||ICONS.FileText).map(([tag,attrs])=>h(tag,attrs)));}
function safeUrl(value){try{const u=new URL(value);return u.protocol==='https:'&&u.hostname==='arxiv.org'?u.href:null;}catch{return null;}}
function SourceLink({paper,children}){const url=safeUrl(paper.source_url);return url?html`<a class="source-link" href=${url} target="_blank" rel="noopener noreferrer">${children||'查看来源'}<${Icon} name="ArrowUpRight" size=${14}/></a>`:html`<span>来源链接不可用</span>`;}
async function api(path,options={}){const r=await fetch('/api'+path,options);if(!r.ok){const data=await r.json().catch(()=>({}));throw Error(typeof data.detail==='string'?data.detail:`请求失败（${r.status}）`);}return r.json();}
function jsonPost(value){return {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(value)};}
function papersOf(run){const values=new Map();for(const step of run?.trace||[]){if(['search_papers','recommend_papers'].includes(step.tool)){for(const paper of step.result?.papers||[]){const old=values.get(paper.doc_id);values.set(paper.doc_id,{...paper,runId:run.id,origins:[...new Set([...(old?.origins||[]),step.tool])]});}}}return [...values.values()];}
function readOf(run,id){return run?.trace?.find(e=>e.tool==='read_paper'&&e.result?.doc_id===id)?.result;}
function ToolTrace({run,openTrace}){
  const [expanded,setExpanded]=useState(false),trace=run.trace||[];
  return html`<div class="tool-box"><button class="tool-disclosure" onClick=${()=>setExpanded(!expanded)} aria-expanded=${expanded}><span class=${`tool-status ${run.status==='running'?'working':''}`}><${Icon} name=${run.status==='running'?'Clock':'Check'} size=${14}/></span><span>${run.status==='running'?(toolNames[run.activeTool]||'正在执行工具…'):`${trace.length} 次真实工具调用`}</span><span class="trace-time">${run.seconds?`${run.seconds.toFixed(2)}s`:''}</span><${Icon} name="ChevronDown" size=${15} class=${expanded?'rotate':''}/></button>${expanded&&html`<div class="tool-steps">${trace.map((e,i)=>html`<details key=${i}><summary><span class=${e.result?.error?'error-dot':'ok-dot'}></span><code>${e.tool}</code><span>${e.result?.error?'拒绝':e.seconds!=null?`${(e.seconds*1000).toFixed(0)}ms`:'已返回'}</span></summary><pre>${JSON.stringify({arguments:e.arguments,result:e.result},null,2)}</pre></details>`)}<button class="text-button" onClick=${()=>openTrace(run)}><${Icon} name="Terminal" size=${14}/>展开完整轨迹</button></div>`}</div>`;
}
function PaperCard({paper,onRead,copy}){return html`<article class="citation-card"><div class="paper-eyebrow"><span class="paper-index"><${Icon} name="FileText" size=${14}/></span><span>arXiv ${paper.doc_id} · v${paper.version}</span><span class="source-badge"><${Icon} name="Check" size=${11}/>原文可追溯</span></div><h3>${paper.title}</h3><blockquote>${paper.quote}</blockquote><div class="paper-actions"><button class="text-button" onClick=${()=>onRead(paper)}><${Icon} name="BookOpen" size=${15}/>阅读原摘要</button><${SourceLink} paper=${paper}/><button class="icon-button copy-button" title="复制这条引用" aria-label="复制这条引用" onClick=${()=>copy(`[${paper.doc_id}v${paper.version}] ${paper.title}\n${paper.quote}\n${paper.source_url}`)}><${Icon} name="Copy" size=${15}/></button></div></article>`;}
function Message({run,onRead,openTrace,copy,retry}){
  const fallback=run.trace?.some(e=>e.tool==='recommend_papers'&&e.result?.cold_user_fallback),cites=run.answer?.citations||[];
  return html`<section class="exchange"><div class="user-message"><span>${run.params?.query||(run.params?.profile==='cold'?'为冷启动用户推荐未读论文。':'根据我的训练画像，推荐一篇未读论文。')}</span><div class="user-meta">${modes[run.params?.mode]?.label} · ${run.params?.profile==='cold'?'冷启动用户':'训练画像用户'}</div></div><div class="assistant-message"><div class="assistant-label"><img src="/mark.svg" width="25" height="25" alt=""/><strong>Papertrail</strong><span>${statusNames[run.status]||run.status}</span><span class="policy-label">固定流程</span></div><${ToolTrace} run=${run} openTrace=${openTrace}/>${fallback&&html`<div class="fallback-note"><${Icon} name="Compass" size=${15}/>该用户没有训练画像，本次推荐使用流行度回退。</div>`}${run.status==='running'?html`<div class="live-note"><span class="pulse-dot"></span>等待真实工具返回结果…</div>`:html`<div class="answer-intro">${run.status==='failed'?'这次请求未完成，已执行步骤和错误均已保留。':run.status==='no_results'?'当前可用目录中没有匹配的未读论文。试试英文关键词，或换一个更宽泛的主题。':run.status==='partial'?'已得到部分结果。搜索与推荐未同时满足要求，下面保留实际读取的来源。':run.status==='cancelled'||run.status==='stopping'?'停止请求已记录；已执行的工具仍计入轨迹。':`已读取 ${cites.length} 篇论文的原 v1 摘要，以下是带来源的摘录。`}</div>`}${run.error&&html`<details class="error-note"><summary>查看真实错误</summary><pre>${run.error}</pre></details>`}<div class="citations">${cites.map(p=>html`<${PaperCard} key=${p.doc_id} paper=${p} onRead=${paper=>onRead({...paper,runId:run.id},run)} copy=${copy}/>` )}</div>${run.status!=='running'&&html`<div class="answer-footer"><span>${cites.length?"原摘要摘录 · 非自由生成总结":"未输出引用"}</span><button class="text-button" onClick=${()=>openTrace(run)}><${Icon} name="Terminal" size=${13}/>调用轨迹</button>${['failed','no_results'].includes(run.status)&&html`<button class="text-button" onClick=${()=>retry(run.params)}>重新尝试</button>`}</div>`}</div></section>`;
}

function App(){
  const [config,setConfig]=useState(null),[connection,setConnection]=useState('connecting'),[threads,setThreads]=useState([]),[runs,setRuns]=useState([]),[current,setCurrent]=useState(null);
  const [thread,setThread]=useState(()=>localStorage.getItem('papertrail.thread')||crypto.randomUUID()),[mode,setMode]=useState('search'),[query,setQuery]=useState(''),[profile,setProfile]=useState('warm');
  const [busy,setBusy]=useState(false),[sideOpen,setSideOpen]=useState(innerWidth>760),[paneOpen,setPaneOpen]=useState(innerWidth>1100),[selected,setSelected]=useState(null),[original,setOriginal]=useState(null),[readError,setReadError]=useState(''),[reading,setReading]=useState(false),[sourceSession,setSourceSession]=useState(null);
  const [modal,setModal]=useState(null),[evidence,setEvidence]=useState(null),[toast,setToast]=useState(''),[theme,setTheme]=useState(()=>localStorage.getItem('papertrail.theme')||'light');
  const scroll=useRef(null),input=useRef(null),controller=useRef(null),activeRun=useRef(null),readVersion=useRef(0);
  useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('papertrail.theme',theme);},[theme]);
  useEffect(()=>{localStorage.setItem('papertrail.thread',thread);},[thread]);
  const refreshThreads=()=>api('/threads').then(setThreads).catch(()=>{});
  useEffect(()=>{api('/config').then(setConfig).catch(e=>setToast(e.message));api('/health').then(()=>setConnection('ready')).catch(()=>setConnection('offline'));refreshThreads();api('/threads/'+thread).then(setRuns).catch(e=>setToast(e.message));const mq=matchMedia('(min-width: 761px)'),pq=matchMedia('(min-width: 1101px)');const resize=()=>{setSideOpen(mq.matches);setPaneOpen(pq.matches);};mq.addEventListener('change',resize);pq.addEventListener('change',resize);return()=>{mq.removeEventListener('change',resize);pq.removeEventListener('change',resize);};},[]);
  useLayoutEffect(()=>{if(scroll.current)scroll.current.scrollTop=scroll.current.scrollHeight;},[runs.length,current?.trace?.length,current?.activeTool,busy]);
  useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),3500);return()=>clearTimeout(timer);},[toast]);
  useEffect(()=>{if(!modal)return;const previous=document.activeElement;const dialog=document.querySelector('.modal');dialog?.querySelector('button')?.focus();const key=e=>{if(e.key==='Escape')setModal(null);if(e.key==='Tab'){const nodes=[...dialog.querySelectorAll('button,a,select,textarea,[tabindex="0"]')].filter(n=>!n.disabled);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};document.addEventListener('keydown',key);return()=>{document.removeEventListener('keydown',key);previous?.focus();};},[modal?.type]);
  const copy=async text=>{try{await navigator.clipboard.writeText(text);setToast('已复制到本机剪贴板');}catch{setToast('复制失败，请手动选择文本。');}};
  async function changeThread(id){if(busy)return;try{setThread(id);setSelected(null);setOriginal(null);setCurrent(null);setRuns(await api('/threads/'+id));if(innerWidth<761)setSideOpen(false);}catch(e){setToast(e.message);}}
  function fresh(){if(busy)return;setThread(crypto.randomUUID());setRuns([]);setCurrent(null);setSelected(null);setOriginal(null);setQuery('');setModal(null);if(innerWidth<761)setSideOpen(false);input.current?.focus();}
  async function openPaper(paper,run){setSelected({...paper,runId:run.id});setPaneOpen(true);setReadError('');setSourceSession(null);const version=++readVersion.current;const known=readOf(run,paper.doc_id);setOriginal(known||null);if(known){setReading(false);return;}setReading(true);try{const value=await api(`/runs/${run.id}/papers/${paper.doc_id}`,{method:'POST'});if(version===readVersion.current){setOriginal(value.paper);setSourceSession(value);}}catch(error){if(version===readVersion.current)setReadError(error.message);}finally{if(version===readVersion.current)setReading(false);}}
  async function perform(explicit){if(busy)return;const picked=explicit||{mode,query,profile},params={mode:picked.mode,query:picked.query||'',profile:picked.profile||'warm'};if(params.mode!=='recommend'&&!params.query?.trim()){setToast('请输入英文关键词或论文标题');input.current?.focus();return;}setBusy(true);setQuery('');setSelected(null);setOriginal(null);activeRun.current=null;let live={id:'pending',params,status:'running',trace:[],answer:null,seconds:0};setCurrent(live);controller.current=new AbortController();let completed=false;
    try{const response=await fetch('/api/runs',{...jsonPost({...params,thread_id:thread}),signal:controller.current.signal});if(!response.ok){const e=await response.json();throw Error(typeof e.detail==='string'?e.detail:'请求参数未通过校验');}const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';
      const consume=event=>{if(event.type==='start'){activeRun.current=event.run_id;live={...live,id:event.run_id};}if(event.type==='tool_start')live={...live,activeTool:event.tool};if(event.type==='tool_result')live={...live,trace:[...live.trace,{tool:event.tool,arguments:event.arguments,result:event.result,seconds:event.seconds}]};if(event.type==='tool_error')live={...live,error:event.message};if(event.type==='done'){completed=true;setRuns(old=>[...old,event.run]);setCurrent(null);refreshThreads();api('/health').then(()=>setConnection('ready')).catch(()=>setConnection('offline'));}else setCurrent({...live});};
      while(true){const {value,done}=await reader.read();buffer+=decoder.decode(value||new Uint8Array(),{stream:!done});const lines=buffer.split('\n');buffer=lines.pop();for(const line of lines)if(line.trim())consume(JSON.parse(line));if(done){if(buffer.trim())consume(JSON.parse(buffer));break;}}
      if(!completed)throw Error('连接中断，最终状态请在历史会话中查看');
    }catch(error){if(error.name==='AbortError'){setCurrent({...live,status:'stopping',error:null});setToast('已请求停止；实际执行轨迹会保存在本地。');}else{setCurrent({...live,status:'failed',error:error.message});setToast(error.message);}}finally{setBusy(false);controller.current=null;refreshThreads();}}
  async function stop(){if(activeRun.current)await api('/runs/'+activeRun.current+'/cancel',{method:'POST'}).catch(()=>{});controller.current?.abort();}
  async function showEvidence(){setModal({type:'evidence'});if(!evidence){try{setEvidence(await api('/evidence'));}catch(e){setToast(e.message);}}}
  const allRuns=[...runs,...(current?[current]:[])],latest=allRuns.at(-1),papers=papersOf(latest),hasMessages=allRuns.length>0;
  const sidebar=html`<aside class=${`sidebar ${sideOpen?'':'closed'}`}><div class="brand"><img src="/mark.svg" alt="" width="31" height="31"/><div><strong>Papertrail</strong><span>论文发现工作台</span></div><button class="icon-button sidebar-close" title="收起导航" aria-label="收起导航" onClick=${()=>setSideOpen(false)}><${Icon} name="PanelLeft" size=${16}/></button></div>
    <button class="new-thread" onClick=${fresh} disabled=${busy}><${Icon} name="Plus" size=${17}/>新会话</button>
    <nav><button class="nav-item active" onClick=${()=>{setModal(null);input.current?.focus();}}><${Icon} name="Compass"/>发现论文</button><button class="nav-item" onClick=${showEvidence}><${Icon} name="GitBranch"/>实验与证据<span class="small-count">83</span></button></nav>
    <div class="history-heading"><span>最近会话</span><${Icon} name="History" size=${13}/></div><div class="history-list">${threads.length?threads.map(t=>html`<button class=${`history-item ${t.id===thread?'selected':''}`} key=${t.id} onClick=${()=>changeThread(t.id)} disabled=${busy}><${Icon} name="MessageSquare" size=${14}/><span>${t.title||'论文发现'}</span></button>`):html`<p class="history-empty">开始一次探索，<br/>你的会话会保存在这里。</p>`}</div>
    <button class="share-note" onClick=${()=>setModal({type:'sharing'})}><${Icon} name="ArrowUpRight" size=${16}/><span>从本地探索，到分享展示<small>了解后续部署方式</small></span></button>
    <footer class="sidebar-footer"><div class="workspace-avatar">P</div><div><strong>本地研究空间</strong><span>10,000 篇 · arXiv v1</span></div><button class="icon-button" title="工作台设置" aria-label="工作台设置" onClick=${()=>setModal({type:'settings'})}><${Icon} name="Settings2" size=${17}/></button></footer>
  </aside>`;
  const center=html`<main class="main-panel"><header class="topbar"><div class="breadcrumb">${!sideOpen&&html`<button class="icon-button" title="展开导航" aria-label="展开导航" onClick=${()=>setSideOpen(true)}><${Icon} name="PanelLeft" size=${18}/></button>`}<span class="breadcrumb-muted">工作台</span><span class="slash">/</span><strong>${hasMessages?'论文探索':'新会话'}</strong></div><div class="topbar-actions"><span class=${`connection ${connection}`}><i></i>${connection==='ready'?'本地服务已连接':connection==='offline'?'服务未连接':'连接中'}</span><button class="icon-button theme-toggle" title="切换明暗主题" aria-label="切换明暗主题" onClick=${()=>setTheme(theme==='dark'?'light':'dark')}><${Icon} name=${theme==='dark'?'Sun':'Moon'} size=${17}/></button><button class=${`icon-button ${paneOpen?'is-on':''}`} title="文献面板" aria-label="文献面板" onClick=${()=>setPaneOpen(!paneOpen)}><${Icon} name="PanelRight" size=${18}/></button></div></header>
    <div class=${`conversation ${hasMessages?'has-messages':''}`} ref=${scroll}>
      ${!hasMessages?html`<div class="welcome"><div class="welcome-mark"><img src="/mark.svg" alt="" width="46" height="46"/></div><div class="welcome-kicker">FOLLOW THE EVIDENCE.</div><h1>让下一篇论文，<br/>更值得读。</h1><p>从一个问题出发，搜索论文、发现兴趣，<br class="desktop-break"/>让每一条线索都有原文可循。</p><div class="welcome-prompts"><button onClick=${()=>{setMode('search');setQuery('retrieval augmented generation');input.current?.focus();}}><${Icon} name="Search"/><strong>从主题开始</strong><span>探索 retrieval augmented generation</span><${Icon} name="ArrowUpRight" size=${15}/></button><button onClick=${()=>{setMode('recommend');setQuery('');input.current?.focus();}}><${Icon} name="Compass"/><strong>发现兴趣之外</strong><span>根据训练画像推荐未读论文</span><${Icon} name="ArrowUpRight" size=${15}/></button><button onClick=${()=>{setMode('mixed');setQuery(config?.example_query||'diffusion models');input.current?.focus();}}><${Icon} name="Layers"/><strong>体验完整链路</strong><span>搜索、推荐，再回到原摘要</span><${Icon} name="ArrowUpRight" size=${15}/></button></div><div class="welcome-foot"><span><${Icon} name="Database" size=${13}/>10,000 篇明确 v1</span><i></i><span>真实后端工具</span><i></i><span>来源可追溯</span></div></div>`:html`<div class="messages">${allRuns.map((run,i)=>html`<${Message} key=${run.id||i} run=${run} onRead=${openPaper} openTrace=${run=>setModal({type:'trace',run})} copy=${copy} retry=${perform}/>` )}</div>`}
    </div>
    <div class="composer-wrap"><form class="composer" onSubmit=${e=>{e.preventDefault();perform();}}><textarea ref=${input} aria-label="论文需求" value=${query} maxLength=${2000} rows="2" onInput=${e=>setQuery(e.currentTarget.value)} onKeyDown=${e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();if(!busy)perform();}}} placeholder=${mode==='recommend'?'准备好发现未读论文了吗？直接发送即可。':'输入英文关键词、论文标题，或选择推荐模式…'} disabled=${busy}></textarea><div class="composer-controls"><div class="mode-control"><${Icon} name=${modes[mode].icon} size=${15}/><select aria-label="任务模式" value=${mode} onChange=${e=>setMode(e.currentTarget.value)} disabled=${busy}>${Object.entries(modes).map(([id,m])=>html`<option value=${id}>${m.label}</option>`)}</select><${Icon} name="ChevronDown" size=${12}/></div><button class="profile-control" type="button" onClick=${()=>setModal({type:'settings'})}><span class=${profile==='warm'?'profile-dot':'profile-dot cold'}></span>${profile==='warm'?'训练画像用户':'冷启动用户'}<${Icon} name="ChevronDown" size=${11}/></button><span class="composer-spacer"></span><span class="fixed-model">Fixed workflow</span>${busy?html`<button class="send-button stopping" type="button" aria-label="停止请求" title="停止请求" onClick=${stop}><${Icon} name="X" size=${19}/></button>`:html`<button class="send-button" type="submit" aria-label="发送请求" title="发送请求" disabled=${mode!=='recommend'&&!query.trim()}><${Icon} name="ArrowUp" size=${19}/></button>`}</div></form><div class="composer-caption"><span>历史回放 · 2025-02-23</span><span>英文论文目录 · 原摘要引用</span><span class="keyboard-hint">Enter 发送 · Shift + Enter 换行</span></div></div>
  </main>`;
  const inspector=paneOpen&&html`<aside class="inspector"><header><div><${Icon} name=${selected?'BookOpen':'FileText'} size=${17}/><strong>${selected?'原文与来源':'文献与来源'}</strong>${!selected&&papers.length>0&&html`<span class="count-badge">${papers.length}</span>`}</div><button class="icon-button" title="关闭文献面板" aria-label="关闭文献面板" onClick=${()=>setPaneOpen(false)}><${Icon} name="X" size=${16}/></button></header><div class="inspector-content">${selected?html`<button class="back-link" onClick=${()=>{setSelected(null);setOriginal(null);readVersion.current++;}}><${Icon} name="ChevronRight" class="back-icon" size=${13}/>返回候选文献</button><div class="detail-label">ARXIV · ${selected.doc_id}v${selected.version||1}</div><h2>${selected.title}</h2><${SourceLink} paper=${selected}>打开原始来源</${SourceLink}>${reading?html`<div class="reading-state"><span class="pulse-dot"></span>重新检索并核验原 v1 摘要…</div>`:readError?html`<div class="error-note">${readError}</div>`:original?html`<div class="verified-line"><${Icon} name="Check" size=${13}/>原始版本已核验 · v${original.version}</div>${sourceSession&&html`<details class="source-session"><summary>${sourceSession.new_source_session?'单独读取会话 · 2 次真实工具调用':'已缓存来源 · 本次未重复执行工具'}</summary><pre>${JSON.stringify(sourceSession.trace?.length?sourceSession.trace:sourceSession.source_session_trace||[],null,2)}</pre><p>这是独立的检索后读取会话，原请求的工具计数保持不变。</p></details>`}<div class="abstract-heading">原摘要 <span>ORIGINAL ABSTRACT</span></div><p class="abstract-text">${original.abstract}</p><div class="detail-provenance"><${Icon} name="GitBranch" size=${15}/><div><strong>引用可以回到原文</strong><p>ID、版本及摘录与缓存原响应核对。来源核验不代表语义相关性或论文结论核验。</p></div></div>`:null}`:papers.length?html`<div class="candidate-intro">本次真实检索与推荐返回的候选。<br/>点击论文查看原始摘要。</div>${papers.map((p,i)=>html`<button class="candidate-card" disabled=${busy} title=${busy?"当前请求完成后可读取原摘要":"读取原摘要"} key=${p.doc_id} onClick=${()=>openPaper(p,latest)}><div><span class="candidate-number">${String(i+1).padStart(2,'0')}</span><span>${p.origins.includes('search_papers')?'搜索':'推荐'} · v${p.version}</span><${Icon} name="ArrowUpRight" size=${13}/></div><h3>${p.title}</h3><span class="candidate-id">arXiv ${p.doc_id}</span></button>` )}`:html`<div class="inspector-empty"><div class="paper-stack"><${Icon} name="FileText" size=${36}/><span></span></div><h3>每一条线索，<br/>都能回到原文。</h3><p>搜索或推荐后，候选文献会出现在这里。点击即可核验原始 v1 摘要与来源。</p><div class="source-fields"><span><${Icon} name="Check" size=${12}/>论文 ID</span><span><${Icon} name="Check" size=${12}/>明确版本</span><span><${Icon} name="Check" size=${12}/>原文链接</span></div></div>`}</div><footer class="inspector-footer"><span class="profile-dot"></span>本地可用目录 · 原始 v1 摘要</footer></aside>`;
  const dialog=modal&&html`<div class="modal-backdrop" onClick=${e=>{if(e.target===e.currentTarget)setModal(null);}}><section class=${`modal ${modal.type==='trace'?'wide':''}`} role="dialog" aria-modal="true" aria-label=${modal.type==='trace'?'真实调用轨迹':modal.type==='settings'?'工作台设置':modal.type==='evidence'?'实验与证据':'后期分享与部署'}><header><div class="modal-heading"><${Icon} name=${modal.type==='trace'?'Terminal':modal.type==='settings'?'SlidersHorizontal':modal.type==='evidence'?'GitBranch':'ArrowUpRight'} size=${20}/><h2>${modal.type==='trace'?'真实调用轨迹':modal.type==='settings'?'工作台设置':modal.type==='evidence'?'实验与证据':'从本地探索，到分享展示'}</h2></div><button class="icon-button" aria-label="关闭对话框" onClick=${()=>setModal(null)}><${Icon} name="X"/></button></header><div class="modal-content">${modal.type==='settings'?html`<p class="modal-description">这些设置只控制展示请求，不更新训练历史。</p><label class="setting-label" for="profile">推荐用户</label><select class="setting-select" id="profile" value=${profile} onChange=${e=>setProfile(e.currentTarget.value)}><option value="warm">训练画像用户 · 个性化内容推荐</option><option value="cold">冷启动用户 · 流行度回退</option></select><label class="setting-label">外观</label><div class="theme-options"><button class=${theme==='light'?'chosen':''} onClick=${()=>setTheme('light')}><${Icon} name="Sun"/>浅色工作台</button><button class=${theme==='dark'?'chosen':''} onClick=${()=>setTheme('dark')}><${Icon} name="Moon"/>深色工作台</button></div><div class="setting-snapshot"><strong>冻结的历史回放</strong><p>历史截止：2024-10-27<br/>当前回放：2025-02-23<br/>默认：BM25 · 内容推荐 · 固定流程</p><small>这里不会自动加入今天的新论文，也不会回写用户反馈。</small></div>`:modal.type==='trace'?html`<p class="modal-description">仅显示实际调用与返回。请求模式：${modes[modal.run.params?.mode]?.label}；LLM 调用 0。</p><div class="trace-toolbar"><span>${modal.run.trace?.length||0} 次工具 · ${modal.run.seconds?.toFixed(2)||'—'}s</span>${modal.run.id!=='pending'&&html`<a class="text-button" href=${'/api/runs/'+modal.run.id+'/export'} download><${Icon} name="Download" size=${14}/>导出本地轨迹</a>`}</div><pre class="full-trace">${JSON.stringify(modal.run.trace||[],null,2)}</pre><p class="small-note">轨迹含本地查询与推荐结果，仅供本机查看；不自动对外分享。</p>`:modal.type==='sharing'?html`<div class="local-pill"><span class="profile-dot"></span>当前为本地交互版</div><p class="modal-description">界面与论文服务已经分开。后续可以保留这套界面，替换成适合远程访问的数据与后端。</p><ol class="sharing-steps"><li><strong>准备可分享的数据</strong><span>使用许可允许的公开样例，保留论文版本与来源；私人反馈和历史轨迹继续留在本机。</span></li><li><strong>部署远程 API</strong><span>补齐身份、访问限制和会话隔离，再连接远程论文服务。</span></li><li><strong>发布前端网站</strong><span>前端使用同源 /api 契约，不依赖本机路径，也不把127.0.0.1误当作远程后端。</span></li></ol><p class="small-note">本轮没有生成在线分享链接，也没有上传本地数据。</p>`:evidence?html`<p class="modal-description">来自已封存实验的聚合事实。两套语料、描述性 dev 与来源核验的边界分别保留。</p><div class="evidence-grid"><div><span>共同 arXiv v1 目录</span><strong>10,000 <small>篇</small></strong><p>统一时间与已读过滤</p></div><div><span>冻结源事实</span><strong>${Object.keys(evidence.claims).length} <small>项</small></strong><p>每项附源路径与 SHA</p></div></div><div class="evidence-section"><h3>生成式检索 · SciFact</h3><p>T5 直接生成 DocID，标题 ID 的 Recall@10 为 ${evidence.claims['search.title.recall@10'].value.toFixed(4)}，BM25 为 ${evidence.claims['search.bm25.recall@10'].value.toFixed(4)}。该 T5 不参与当前万篇请求。</p></div><div class="evidence-section"><h3>冷论文融合 · 描述性 dev</h3><p>内容推荐冷命中 ${evidence.claims['recommend.content.cold_item.hits'].value}，支持门控 ${evidence.claims['recommend.gated.cold_item.hits'].value}，分母均为 33,557 个冷论文事件。默认仍保留内容推荐。</p></div><div class="evidence-section"><h3>Agent 调度 · 12 个受控任务</h3><div class="result-bars">${[['fixed','固定流程'],['llm_agent','原 LLM'],['constrained','状态约束 LLM']].map(([id,label])=>html`<div><span>${label}</span><strong>${evidence.claims['agent.'+id+'.task_success'].value}/12</strong></div>`)}</div><p>约束未过预设门槛，当前界面使用固定流程；规则收益不归为模型推理能力。</p></div><details class="evidence-sources"><summary>查看源事实与相对路径</summary><pre>${JSON.stringify(evidence.claims,null,2)}</pre></details>`:html`<div class="reading-state">正在读取冻结证据…</div>`}</div></section></div>`;
  return html`<div class="app-shell">${sideOpen&&innerWidth<761&&html`<button class="sidebar-backdrop" aria-label="关闭导航" onClick=${()=>setSideOpen(false)}></button>`}${sidebar}${center}${inspector}${dialog}${toast&&html`<div class="toast" role="status"><${Icon} name=${/失败|未|中断/.test(toast)?'CircleAlert':'Check'} size=${15}/>${toast}</div>`}</div>`;
}
render(html`<${App}/>`,document.getElementById('app'));
